export function CDSSection(i){const n=i.responsibilities.map(i=>`<li>${i}</li>`).join(""),s=i.history.map(i=>`\n        <div class="cds-timeline-item">\n            <div class="cds-timeline-year">${i.year}</div>\n            <div class="cds-timeline-content">\n                <h4>${i.title}</h4>\n                <p>${i.detail}</p>\n            </div>\n        </div>\n    `).join("");return`\n        <div class="cds-section">\n            <div class="cds-header">\n                <div class="cds-emblem">CDS</div>\n                <div>\n                    <h3>${i.title}</h3>\n                    <p class="cds-current">${i.currentHolder} (since ${i.since})</p>\n                </div>\n            </div>\n            <div class="cds-body">\n                <p class="cds-overview">${i.overview}</p>\n                <div class="cds-section-block">\n                    <h4>Responsibilities</h4>\n                    <ul class="cds-responsibilities">${n}</ul>\n                </div>\n                <div class="cds-section-block">\n                    <h4>Organizational Structure</h4>\n                    <p class="cds-org">${i.organizationalStructure}</p>\n                </div>\n                <div class="cds-section-block">\n                    <h4>History</h4>\n                    <div class="cds-timeline">\n                        ${s}\n                    </div>\n                </div>\n            </div>\n        </div>\n    `}